/* EJE FILTERS — dos niveles */
.eje-filters{display:flex;gap:0.4rem;flex-wrap:wrap;margin-bottom:0.5rem;}
.eje-filters-sub{display:flex;gap:0.3rem;flex-wrap:wrap;margin-bottom:1.2rem;min-height:1.8rem;}
.eje-pill{background:none;border:1px solid var(--border);color:var(--text2);padding:0.28rem 0.8rem;border-radius:20px;cursor:pointer;font-size:0.69rem;font-family:var(--font-mono);transition:var(--trans);display:flex;align-items:center;gap:0.3rem;}
.eje-pill:hover{border-color:var(--border2);color:var(--text);}
.eje-pill.active{background:var(--accent-bg);border-color:var(--accent);color:var(--accent);}
.eje-pill.sub{font-size:0.63rem;padding:0.2rem 0.65rem;border-radius:12px;}
.eje-pill.sub.active{font-weight:600;}
/* PAGINACION */
.pag-row{display:flex;align-items:center;justify-content:center;gap:0.4rem;margin-top:1.6rem;flex-wrap:wrap;}
.pag-btn{background:var(--surface);border:1px solid var(--border);color:var(--text2);padding:0.35rem 0.75rem;border-radius:var(--radius);cursor:pointer;font-size:0.73rem;font-family:var(--font-mono);transition:var(--trans);min-width:36px;text-align:center;}
.pag-btn:hover{border-color:var(--border2);color:var(--text);}
.pag-btn.active{background:var(--accent-bg);border-color:var(--accent);color:var(--accent);font-weight:700;}
.pag-btn:disabled{opacity:0.35;cursor:default;}
.pag-info{font-size:0.65rem;color:var(--text3);font-family:var(--font-mono);padding:0 0.4rem;}

