const EJES_CONFIG={
  'Neurociencia y Biología':{icon:'🔬',color:'#1abc9c',sub:{'Neurociencia':'🧬','Biología y Longevidad':'💊'}},
  'Psicología y Conducta':{icon:'🧠',color:'#9b59b6',sub:{'Cognitiva':'💭','Social':'👥','Interpersonal':'🤝','Influencia':'⚡'}},
  'Pensamiento y Civilización':{icon:'⚖️',color:'#5dade2',sub:{'Epistemología':'🔭','Filosofía':'🏛️','Historia':'📜'}},
  'Economía y Mercados':{icon:'📈',color:'#c9a84c',sub:{'Economía':'💰'}},
  'Desarrollo Humano':{icon:'🌱',color:'#e67e22',sub:{'Mentalidad':'🎯','Crecimiento Personal':'✨'}}
};
function ejeIcon(e){
  if(!e)return'📖';
  for(const[p,cfg]of Object.entries(EJES_CONFIG)){if(e===p)return cfg.icon;if(cfg.sub[e])return cfg.sub[e];}
  return'📖';
}
function ejeColor(e){
  if(!e)return'#5c5650';
  for(const[p,cfg]of Object.entries(EJES_CONFIG)){if(e===p||cfg.sub[e])return cfg.color;}
  return'#5c5650';
}
function ejeClass(e){return'eje-'+(e||'').replace(/[^a-zA-Z0-9]/g,'_');}
function normalizeEje(e){return e;}
function getEjePrincipal(l){return l.eje_principal||l.eje||'';}
function getSubEje(l){return l.sub_eje||l.eje||'';}

